const data = $input.item.json;
if (data.score < 60) {
  return [];
}

const prompt = `Evalue la pertinence de cette offre pour une alternance de Technicien Supérieur Systèmes et Réseaux (TSSR) à Toulouse.

Entreprise: ${data.entreprise}
Poste: ${data.poste}
Contrat: ${data.contract}
Localisation: ${data.localisation}
Description: ${(data.description || '').slice(0, 2000)}

Critères :
- C'est une VRAIE entreprise (pas un organisme de formation) ?
- Le poste correspond au TSSR (systèmes, réseaux, support, infrastructure, helpdesk) ?
- C'est bien une alternance ou un contrat d'apprentissage ?
- C'est accessible depuis Toulouse (< 60 km ou télétravail) ?

Réponds uniquement en JSON valide : { "rating": 8, "action": "apply", "reason": "raison courte en français" }`;

return [{ json: { ...data, groq_body: {
  model: 'llama-3.3-70b-versatile',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'Tu es un assistant qui évalue des offres d\'emploi pour une alternance TSSR. Réponds uniquement en JSON.' },
    { role: 'user', content: prompt }
  ]
} } }];

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const src = $('Analyser').all();
const idx = $itemIndex;
const orig = src[idx] ? src[idx].json : {};
const data = $input.item.json;

let groq = { rating: 0, action: 'skip', reason: 'IA indisponible' };
try {
  const content = data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
  if (content) groq = JSON.parse(content);
} catch (e) {}

if (groq.rating < 5) return [];

const adequation = groq.rating >= 7 ? 'Forte' : 'Moyenne';

const notionBody = {
  parent: { database_id: '${NOTION_DATABASE_ID}' },
  properties: {
    'Entreprise': { title: [{ text: { content: orig.entreprise || 'Inconnu' } }] },
    'Poste': { rich_text: [{ text: { content: (orig.poste || '').slice(0, 200) } }] },
    'Statut': { select: { name: 'À contacter' } },
    'Source': { select: { name: orig.source || 'JobBot' } },
    'Localisation': { rich_text: [{ text: { content: orig.localisation || '' } }] },
    'Lien offre': { url: orig.url || null },
    'Adéquation TSSR': { select: { name: adequation } },
    'Notes': { rich_text: [{ text: { content: `${groq.reason} — Action: ${groq.action} (${groq.rating}/10)` } }] }
  }
};

const msg = `🎯 <b>${esc(orig.poste)}</b>\n🏢 ${esc(orig.entreprise)} — ${esc(orig.localisation)}\n⭐ ${groq.rating}/10 — ${esc(groq.reason)}\n💡 ${esc(groq.action)}` + (orig.url ? `\n🔗 <a href="${orig.url}">Voir l'offre</a>` : '');

return [{ json: { ...orig, groq, notionBody, msg } }];
